&reftitle.description;
public Yaf_Application::__construct stringarrayconfig stringnullenvironnull
Instancie un objet Yaf_Application. Le constructeur initialise également l'application singleton, le Yaf_Loader et le Yaf_Dispatcher ; il doit donc être appelé avant toute utilisation de ces derniers.

  &reftitle.examples;

   Exemple avec Yaf_Application::__construct


<?php
defined('APPLICATION_PATH')                  // APPLICATION_PATH sera utilisé dans le fichier de configuration ini
    || define('APPLICATION_PATH', __DIR__);

$application = new Yaf_Application(APPLICATION_PATH.'/conf/application.ini');
$application->bootstrap()->run();
?>




   Exemple avec Yaf_Application::__construct


<?php
$config = array(
    "application" => array(
        "directory" => realpath(dirname(__FILE__)) . "/application",
    ),
);

/** Yaf_Application */
$application = new Yaf_Application($config);
$application->bootstrap()->run();
?>
